mapper.select:
SELECT id,name,city,address,price,original_price,facilities,stars,overall_rating,review_count,longitude,latitude,hi.image AS mainImage
FROM hotel LEFT JOIN hotel_image AS hi ON hotel.id = hi.hotel_id AND hi.sort_order = 1

    AND stars = #{stars}
    AND city = #{city}
    AND price >= #{minPrice}
    AND price <= #{maxPrice}


        AND (

             FIND_IN_SET(#{facility}, facilities) > 0

        )




    ORDER BY price ASC, id ASC
    ORDER BY price DESC, id ASC

        ORDER BY (
            6371 * 2 * ASIN(SQRT(
                POW(SIN(RADIANS(hotel.latitude - #{userLat}) / 2), 2) +
                COS(RADIANS(#{userLat})) * COS(RADIANS(hotel.latitude)) *
                POW(SIN(RADIANS(hotel.longitude - #{userLng}) / 2), 2)
            ))
        ) ASC, id ASC


    ORDER BY overall_rating DESC, id ASC

    LIMIT #{offset}, #{size}

